    RTIBool EnergyStorageInfo_copy(
        EnergyStorageInfo* dst,
        const EnergyStorageInfo* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyFloat (
                &dst->highStateOfCharge, 
                &src->highStateOfCharge)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->lowStateOfCharge, 
                &src->lowStateOfCharge)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minTemperature, 
                &src->minTemperature)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->nomTemperature, 
                &src->nomTemperature)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxTemperature, 
                &src->maxTemperature)) { 
                return RTI_FALSE;
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

