    RTIBool EngineInfo_copy(
        EngineInfo* dst,
        const EngineInfo* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyFloat (
                &dst->minOilPressure, 
                &src->minOilPressure)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxOilPressure, 
                &src->maxOilPressure)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minCoolantTemperature, 
                &src->minCoolantTemperature)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxCoolantTemperature, 
                &src->maxCoolantTemperature)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minEngineSpeed, 
                &src->minEngineSpeed)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxEngineSpeed, 
                &src->maxEngineSpeed)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minWetStackPreventionLoad, 
                &src->minWetStackPreventionLoad)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minWetStackMitigationLoad, 
                &src->minWetStackMitigationLoad)) { 
                return RTI_FALSE;
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

