    RTIBool EngineState_initialize_w_params(
        EngineState *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        sample->operatingState = tms::EOS_UNKNOWN;
        sample->oilPressure = 0.0f;

        sample->coolantTemperature = 0.0f;

        sample->speed = 0.0f;

        if (!allocParams->allocate_optional_members) {
            sample->wetStack=NULL;
        } else {   
            if (allocParams->allocate_memory){
                sample->wetStack = new (std::nothrow)   DDS_Float ();
                if (sample->wetStack==NULL) {
                    return RTI_FALSE;
                }
                if (!RTICdrType_initFloat(sample->wetStack)) {
                    return RTI_FALSE;
                }

            } else {

                if (sample->wetStack != NULL) {
                    if (!RTICdrType_initFloat(sample->wetStack)) {
                        return RTI_FALSE;
                    }
                }

            }

        }
        sample->engineRuntime = 0.0f;

        if (!allocParams->allocate_optional_members) {
            sample->fuelConsumptionRate=NULL;
        } else {   
            if (allocParams->allocate_memory){
                sample->fuelConsumptionRate = new (std::nothrow)   DDS_Float ();
                if (sample->fuelConsumptionRate==NULL) {
                    return RTI_FALSE;
                }
                if (!RTICdrType_initFloat(sample->fuelConsumptionRate)) {
                    return RTI_FALSE;
                }

            } else {

                if (sample->fuelConsumptionRate != NULL) {
                    if (!RTICdrType_initFloat(sample->fuelConsumptionRate)) {
                        return RTI_FALSE;
                    }
                }

            }

        }
        return RTI_TRUE;
    }
