    void EngineState_finalize_w_params(
        EngineState* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        tms::EngineOperatingState_finalize_w_params(&sample->operatingState,deallocParams);

        if (deallocParams->delete_optional_members) {
            if (sample->wetStack != NULL) {

                delete  sample->wetStack;
                sample->wetStack=NULL;
            }
        }

        if (deallocParams->delete_optional_members) {
            if (sample->fuelConsumptionRate != NULL) {

                delete  sample->fuelConsumptionRate;
                sample->fuelConsumptionRate=NULL;
            }
        }
    }

