    RTIBool EngineState_copy(
        EngineState* dst,
        const EngineState* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::EngineOperatingState_copy(
                &dst->operatingState,
                (const tms::EngineOperatingState*)&src->operatingState)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyFloat (
                &dst->oilPressure, 
                &src->oilPressure)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->coolantTemperature, 
                &src->coolantTemperature)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->speed, 
                &src->speed)) { 
                return RTI_FALSE;
            }
            if (src->wetStack!=NULL) {
                if (dst->wetStack==NULL) {

                    dst->wetStack = new (std::nothrow)   DDS_Float ();
                    if (dst->wetStack==NULL) {
                        return RTI_FALSE;
                    }

                    if (!RTICdrType_initFloat(dst->wetStack)) {
                        return RTI_FALSE;
                    }
                }
                if (!RTICdrType_copyFloat (
                    dst->wetStack, 
                    src->wetStack)) { 
                    return RTI_FALSE;
                }
            } else {
                if (dst->wetStack != NULL) {
                    delete  dst->wetStack;
                    dst->wetStack=NULL;
                }
            }
            if (!RTICdrType_copyFloat (
                &dst->engineRuntime, 
                &src->engineRuntime)) { 
                return RTI_FALSE;
            }
            if (src->fuelConsumptionRate!=NULL) {
                if (dst->fuelConsumptionRate==NULL) {

                    dst->fuelConsumptionRate = new (std::nothrow)   DDS_Float ();
                    if (dst->fuelConsumptionRate==NULL) {
                        return RTI_FALSE;
                    }

                    if (!RTICdrType_initFloat(dst->fuelConsumptionRate)) {
                        return RTI_FALSE;
                    }
                }
                if (!RTICdrType_copyFloat (
                    dst->fuelConsumptionRate, 
                    src->fuelConsumptionRate)) { 
                    return RTI_FALSE;
                }
            } else {
                if (dst->fuelConsumptionRate != NULL) {
                    delete  dst->fuelConsumptionRate;
                    dst->fuelConsumptionRate=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

