    RTIBool LoadStepResponse_copy(
        LoadStepResponse* dst,
        const LoadStepResponse* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyFloat (
                &dst->loadStepLowRealPower, 
                &src->loadStepLowRealPower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->loadStepHighRealPower, 
                &src->loadStepHighRealPower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->loadStepLowReactivePower, 
                &src->loadStepLowReactivePower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->loadStepHighReactivePower, 
                &src->loadStepHighReactivePower)) { 
                return RTI_FALSE;
            }
            if (!tms::Curve2D_copy(
                &dst->loadAcceptanceFrequency,
                (const tms::Curve2D*)&src->loadAcceptanceFrequency)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadAcceptanceVoltage,
                (const tms::Curve2D*)&src->loadAcceptanceVoltage)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadAcceptanceRealPower,
                (const tms::Curve2D*)&src->loadAcceptanceRealPower)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadAcceptanceReactivePower,
                (const tms::Curve2D*)&src->loadAcceptanceReactivePower)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadRejectionFrequency,
                (const tms::Curve2D*)&src->loadRejectionFrequency)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadRejectionVoltage,
                (const tms::Curve2D*)&src->loadRejectionVoltage)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadRejectionRealPower,
                (const tms::Curve2D*)&src->loadRejectionRealPower)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->loadRejectionReactivePower,
                (const tms::Curve2D*)&src->loadRejectionReactivePower)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

