    RTIBool LoadSharingInfo_initialize_w_params(
        LoadSharingInfo *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        sample->portNumber = 0;

        sample->supportsDroop = 0;

        sample->supportsMultiSegmentDroop = 0;

        sample->supportsConstantPower = 0;

        sample->minRealPower = 0.0f;

        sample->maxRealPower = 0.0f;

        if (!allocParams->allocate_optional_members) {
            sample->maxOverloadRealPower=NULL;
        } else {   
            if (allocParams->allocate_memory) {
                sample->maxOverloadRealPower = new (std::nothrow)   tms::Curve2D ();
                if (sample->maxOverloadRealPower==NULL) {
                    return RTI_FALSE;
                }
                if (!tms::Curve2D_initialize_w_params(
                    sample->maxOverloadRealPower,
                    allocParams)) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->maxOverloadRealPower!=NULL) {
                    if (!tms::Curve2D_initialize_w_params(
                        sample->maxOverloadRealPower,
                        allocParams)) {
                        return RTI_FALSE;
                    }
                }   
            }
        }
        sample->minReactivePower = 0.0f;

        sample->maxReactivePower = 0.0f;

        sample->maxApparentPower = 0.0f;

        sample->powerFactor = 0.0f;

        if (!allocParams->allocate_optional_members) {
            sample->loadResponse=NULL;
        } else {   
            if (allocParams->allocate_memory) {
                sample->loadResponse = new (std::nothrow)   tms::LoadStepResponseSequence ();
                if (sample->loadResponse==NULL) {
                    return RTI_FALSE;
                }
                if (!tms::LoadStepResponseSequence_initialize_w_params(
                    sample->loadResponse,
                    allocParams)) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->loadResponse!=NULL) {
                    if (!tms::LoadStepResponseSequence_initialize_w_params(
                        sample->loadResponse,
                        allocParams)) {
                        return RTI_FALSE;
                    }
                }   
            }
        }
        return RTI_TRUE;
    }
