    RTIBool LoadSharingInfo_copy(
        LoadSharingInfo* dst,
        const LoadSharingInfo* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyLong (
                &dst->portNumber, 
                &src->portNumber)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->supportsDroop, 
                &src->supportsDroop)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->supportsMultiSegmentDroop, 
                &src->supportsMultiSegmentDroop)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->supportsConstantPower, 
                &src->supportsConstantPower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minRealPower, 
                &src->minRealPower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxRealPower, 
                &src->maxRealPower)) { 
                return RTI_FALSE;
            }
            if (src->maxOverloadRealPower!=NULL) {
                if (dst->maxOverloadRealPower==NULL) {

                    dst->maxOverloadRealPower = new (std::nothrow)   tms::Curve2D ();
                    if (dst->maxOverloadRealPower==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::Curve2D_initialize_ex(
                        dst->maxOverloadRealPower, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::Curve2D_copy(
                    dst->maxOverloadRealPower,
                    (const tms::Curve2D*)src->maxOverloadRealPower)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->maxOverloadRealPower != NULL) {
                    tms::Curve2D_finalize_w_params(dst->maxOverloadRealPower, deallocParams);
                    delete  dst->maxOverloadRealPower;
                    dst->maxOverloadRealPower=NULL;
                }
            }
            if (!RTICdrType_copyFloat (
                &dst->minReactivePower, 
                &src->minReactivePower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxReactivePower, 
                &src->maxReactivePower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxApparentPower, 
                &src->maxApparentPower)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->powerFactor, 
                &src->powerFactor)) { 
                return RTI_FALSE;
            }
            if (src->loadResponse!=NULL) {
                if (dst->loadResponse==NULL) {

                    dst->loadResponse = new (std::nothrow)   tms::LoadStepResponseSequence ();
                    if (dst->loadResponse==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::LoadStepResponseSequence_initialize_ex(
                        dst->loadResponse, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::LoadStepResponseSequence_copy(
                    dst->loadResponse,
                    (const tms::LoadStepResponseSequence*)src->loadResponse)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->loadResponse != NULL) {
                    tms::LoadStepResponseSequence_finalize_w_params(dst->loadResponse, deallocParams);
                    delete  dst->loadResponse;
                    dst->loadResponse=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

