    RTIBool StorageInfo_initialize_w_params(
        StorageInfo *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        if (!tms::StorageFeatureSequence_initialize_w_params(
            &sample->features,
            allocParams)) {
            return RTI_FALSE;
        }
        sample->maxChargeEnergy = 0.0f;

        if (!tms::LoadSharingInfo_initialize_w_params(
            &sample->loadSharing,
            allocParams)) {
            return RTI_FALSE;
        }
        if (!tms::EnergyStartStopLevelSequence_initialize_w_params(
            &sample->supportedEnergyStartStopLevels,
            allocParams)) {
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }
