    void StorageInfo_finalize_ex(
        StorageInfo* sample,RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParams =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;

        if (sample==NULL) {
            return;
        } 

        deallocParams.delete_pointers = (DDS_Boolean)deletePointers;

        tms::StorageInfo_finalize_w_params(
            sample,&deallocParams);
    }

    void StorageInfo_finalize_w_params(
        StorageInfo* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        tms::StorageFeatureSequence_finalize_w_params(&sample->features,deallocParams);

        tms::LoadSharingInfo_finalize_w_params(&sample->loadSharing,deallocParams);

        tms::EnergyStartStopLevelSequence_finalize_w_params(&sample->supportedEnergyStartStopLevels,deallocParams);

    }

    void StorageInfo_finalize_optional_members(
        StorageInfo* sample, RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParamsTmp =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
        struct DDS_TypeDeallocationParams_t * deallocParams =
        &deallocParamsTmp;

        if (sample==NULL) {
            return;
        } 
        if (deallocParams) {} /* To avoid warnings */

        deallocParamsTmp.delete_pointers = (DDS_Boolean)deletePointers;
        deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;

        tms::LoadSharingInfo_finalize_optional_members(&sample->loadSharing, deallocParams->delete_pointers);
    }

    RTIBool StorageInfo_copy(
        StorageInfo* dst,
        const StorageInfo* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::StorageFeatureSequence_copy(
                &dst->features,
                (const tms::StorageFeatureSequence*)&src->features)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyFloat (
                &dst->maxChargeEnergy, 
                &src->maxChargeEnergy)) { 
                return RTI_FALSE;
            }
            if (!tms::LoadSharingInfo_copy(
                &dst->loadSharing,
                (const tms::LoadSharingInfo*)&src->loadSharing)) {
                return RTI_FALSE;
            } 
            if (!tms::EnergyStartStopLevelSequence_copy(
                &dst->supportedEnergyStartStopLevels,
                (const tms::EnergyStartStopLevelSequence*)&src->supportedEnergyStartStopLevels)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

