    RTIBool ControlHardwareUpdate_copy(
        ControlHardwareUpdate* dst,
        const ControlHardwareUpdate* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::ClockMonotonic_copy(
                &dst->timestamp,
                (const tms::ClockMonotonic*)&src->timestamp)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyFloat (
                &dst->processorUsage, 
                &src->processorUsage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->memoryUsage, 
                &src->memoryUsage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->networkUsage, 
                &src->networkUsage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->storageUsage, 
                &src->storageUsage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->temperature, 
                &src->temperature)) { 
                return RTI_FALSE;
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

