    RTIBool ClockState_initialize_w_params(
        ClockState *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        if (allocParams->allocate_memory) {
            sample->deviceId = DDS_String_alloc(((tms::Identity_MAXLEN)));
            if (sample->deviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->deviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
            }
            if (sample->deviceId == NULL) {
                return RTI_FALSE;
            }
        } else {
            if (sample->deviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->deviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
                if (sample->deviceId == NULL) {
                    return RTI_FALSE;
                }
            }
        }

        if (!tms::ClockMonotonic_initialize_w_params(
            &sample->monotonic,
            allocParams)) {
            return RTI_FALSE;
        }
        sample->monotonicPersistence = tms::CMPT_UNKNOWN;
        if (!tms::ClockRealtime_initialize_w_params(
            &sample->realtime,
            allocParams)) {
            return RTI_FALSE;
        }
        sample->realtimeSource = tms::CLOCK_UNKNOWN;
        if (!tms::ClockRealtime_initialize_w_params(
            &sample->realtimeSetTime,
            allocParams)) {
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }
