    void ClockState_finalize_w_params(
        ClockState* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        if (sample->deviceId != NULL) {
            DDS_String_free(sample->deviceId);
            sample->deviceId=NULL;

        }
        tms::ClockMonotonic_finalize_w_params(&sample->monotonic,deallocParams);

        tms::ClockMonotonicPersistenceType_finalize_w_params(&sample->monotonicPersistence,deallocParams);

        tms::ClockRealtime_finalize_w_params(&sample->realtime,deallocParams);

        tms::ClockSource_finalize_w_params(&sample->realtimeSource,deallocParams);

        tms::ClockRealtime_finalize_w_params(&sample->realtimeSetTime,deallocParams);

    }

