    RTIBool ClockState_copy(
        ClockState* dst,
        const ClockState* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::ClockMonotonic_copy(
                &dst->monotonic,
                (const tms::ClockMonotonic*)&src->monotonic)) {
                return RTI_FALSE;
            } 
            if (!tms::ClockMonotonicPersistenceType_copy(
                &dst->monotonicPersistence,
                (const tms::ClockMonotonicPersistenceType*)&src->monotonicPersistence)) {
                return RTI_FALSE;
            } 
            if (!tms::ClockRealtime_copy(
                &dst->realtime,
                (const tms::ClockRealtime*)&src->realtime)) {
                return RTI_FALSE;
            } 
            if (!tms::ClockSource_copy(
                &dst->realtimeSource,
                (const tms::ClockSource*)&src->realtimeSource)) {
                return RTI_FALSE;
            } 
            if (!tms::ClockRealtime_copy(
                &dst->realtimeSetTime,
                (const tms::ClockRealtime*)&src->realtimeSetTime)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

