    RTIBool DeviceConfigRequest_copy(
        DeviceConfigRequest* dst,
        const DeviceConfigRequest* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->requestingDeviceId
                ,
                src->requestingDeviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyStringEx (
                &dst->targetDeviceId
                ,
                src->targetDeviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::ConfigId_copy(
                &dst->config,
                (const tms::ConfigId*)&src->config)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

