        RTIXCdrSampleAccessInfo_INITIALIZER;

        if (is_initialized) {
            return (RTIXCdrSampleAccessInfo*) &PowerPortInfo_g_sampleAccessInfo;
        }

        RTIXCdrHeap_allocateStruct(
            &sample, 
            tms::PowerPortInfo);
        if (sample == NULL) {
            return NULL;
        }

        PowerPortInfo_g_memberAccessInfos[0].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->portNumber - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[1].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->wiring - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[2].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->directionality - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[3].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->hasSwitch - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[4].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->hasExternalMeter - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[5].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->hasInternalMeter - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[6].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->hasSummaryMeasurementUpdate - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[7].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->minAmperage - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[8].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->maxAmperage - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[9].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->shortCircuitAmperage - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[10].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->minVoltage - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[11].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->maxVoltage - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[12].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->minFrequency - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[13].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->maxFrequency - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[14].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->connectorInfo - (char *)sample);

        PowerPortInfo_g_memberAccessInfos[15].bindingMemberValueOffset[0] = 
        (RTIXCdrUnsignedLong) ((char *)&sample->switchInfo - (char *)sample);

        PowerPortInfo_g_sampleAccessInfo.memberAccessInfos = 
        PowerPortInfo_g_memberAccessInfos;

        {
            size_t candidateTypeSize = sizeof(PowerPortInfo);

            if (candidateTypeSize > RTIXCdrLong_MAX) {
                PowerPortInfo_g_sampleAccessInfo.typeSize[0] =
                RTIXCdrLong_MAX;
            } else {
                PowerPortInfo_g_sampleAccessInfo.typeSize[0] =
                (RTIXCdrUnsignedLong) candidateTypeSize;
            }
        }

        PowerPortInfo_g_sampleAccessInfo.useGetMemberValueOnlyWithRef =
        RTI_XCDR_TRUE;

        PowerPortInfo_g_sampleAccessInfo.getMemberValuePointerFcn = 
        PowerPortInfo_get_member_value_pointer;

        PowerPortInfo_g_sampleAccessInfo.languageBinding = 
        RTI_XCDR_TYPE_BINDING_CPP ;

        RTIXCdrHeap_freeStruct(sample);
        is_initialized = RTI_TRUE;
        return (RTIXCdrSampleAccessInfo*) &PowerPortInfo_g_sampleAccessInfo;
