    RTIBool PowerPortInfo_initialize(
        PowerPortInfo* sample)
    {
        return tms::PowerPortInfo_initialize_ex(
            sample, 
            RTI_TRUE, 
            RTI_TRUE);
    }
    RTIBool PowerPortInfo_initialize_w_params(
        PowerPortInfo *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        sample->portNumber = 0;

        sample->wiring = tms::WIRING_UNKNOWN;
        sample->directionality = tms::PPD_UNKNOWN;
        sample->hasSwitch = 0;

        sample->hasExternalMeter = 0;

        sample->hasInternalMeter = 0;

        sample->hasSummaryMeasurementUpdate = 0;

        sample->minAmperage = 0.0f;

        sample->maxAmperage = 0.0f;

        sample->shortCircuitAmperage = 0.0f;

        sample->minVoltage = 0.0f;

        sample->maxVoltage = 0.0f;

        if (!allocParams->allocate_optional_members) {
            sample->minFrequency=NULL;
        } else {   
            if (allocParams->allocate_memory){
                sample->minFrequency = new (std::nothrow)   DDS_Float ();
                if (sample->minFrequency==NULL) {
                    return RTI_FALSE;
                }
                if (!RTICdrType_initFloat(sample->minFrequency)) {
                    return RTI_FALSE;
                }

            } else {

                if (sample->minFrequency != NULL) {
                    if (!RTICdrType_initFloat(sample->minFrequency)) {
                        return RTI_FALSE;
                    }
                }

            }

        }
        if (!allocParams->allocate_optional_members) {
            sample->maxFrequency=NULL;
        } else {   
            if (allocParams->allocate_memory){
                sample->maxFrequency = new (std::nothrow)   DDS_Float ();
                if (sample->maxFrequency==NULL) {
                    return RTI_FALSE;
                }
                if (!RTICdrType_initFloat(sample->maxFrequency)) {
                    return RTI_FALSE;
                }

            } else {

                if (sample->maxFrequency != NULL) {
                    if (!RTICdrType_initFloat(sample->maxFrequency)) {
                        return RTI_FALSE;
                    }
                }

            }

        }
        if (!tms::PowerConnectorInfo_initialize_w_params(
            &sample->connectorInfo,
            allocParams)) {
            return RTI_FALSE;
        }
        if (!allocParams->allocate_optional_members) {
            sample->switchInfo=NULL;
        } else {   
            if (allocParams->allocate_memory) {
                sample->switchInfo = new (std::nothrow)   tms::PowerSwitchInfo ();
                if (sample->switchInfo==NULL) {
                    return RTI_FALSE;
                }
                if (!tms::PowerSwitchInfo_initialize_w_params(
                    sample->switchInfo,
                    allocParams)) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->switchInfo!=NULL) {
                    if (!tms::PowerSwitchInfo_initialize_w_params(
                        sample->switchInfo,
                        allocParams)) {
                        return RTI_FALSE;
                    }
                }   
            }
        }
        return RTI_TRUE;
    }
    RTIBool PowerPortInfo_initialize_ex(
        PowerPortInfo *sample,
        RTIBool allocatePointers, 
        RTIBool allocateMemory)
    {

        struct DDS_TypeAllocationParams_t allocParams =
        DDS_TYPE_ALLOCATION_PARAMS_DEFAULT;

        allocParams.allocate_pointers =  (DDS_Boolean)allocatePointers;
        allocParams.allocate_memory = (DDS_Boolean)allocateMemory;

        return tms::PowerPortInfo_initialize_w_params(
            sample,
            &allocParams);
    }

    RTIBool PowerPortInfo_finalize_w_return(
        PowerPortInfo* sample)
    {
        tms::PowerPortInfo_finalize_ex(sample, RTI_TRUE);

        return RTI_TRUE;
    }

    void PowerPortInfo_finalize(
        PowerPortInfo* sample)
    {

        tms::PowerPortInfo_finalize_ex(sample,RTI_TRUE);
    }

    void PowerPortInfo_finalize_ex(
        PowerPortInfo* sample,RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParams =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;

        if (sample==NULL) {
            return;
        } 

        deallocParams.delete_pointers = (DDS_Boolean)deletePointers;

        tms::PowerPortInfo_finalize_w_params(
            sample,&deallocParams);
    }

    void PowerPortInfo_finalize_w_params(
        PowerPortInfo* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        tms::CircuitWiring_finalize_w_params(&sample->wiring,deallocParams);

        tms::PowerPortDirectionality_finalize_w_params(&sample->directionality,deallocParams);

        if (deallocParams->delete_optional_members) {
            if (sample->minFrequency != NULL) {

                delete  sample->minFrequency;
                sample->minFrequency=NULL;
            }
        }
        if (deallocParams->delete_optional_members) {
            if (sample->maxFrequency != NULL) {

                delete  sample->maxFrequency;
                sample->maxFrequency=NULL;
            }
        }
        tms::PowerConnectorInfo_finalize_w_params(&sample->connectorInfo,deallocParams);

        if (deallocParams->delete_optional_members) {
            if (sample->switchInfo != NULL) {
                tms::PowerSwitchInfo_finalize_w_params(sample->switchInfo,deallocParams);

                delete  sample->switchInfo;
                sample->switchInfo=NULL;
            }
        }
    }

    void PowerPortInfo_finalize_optional_members(
        PowerPortInfo* sample, RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParamsTmp =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
        struct DDS_TypeDeallocationParams_t * deallocParams =
        &deallocParamsTmp;

        if (sample==NULL) {
            return;
        } 
        if (deallocParams) {} /* To avoid warnings */

        deallocParamsTmp.delete_pointers = (DDS_Boolean)deletePointers;
        deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;

        if (sample->minFrequency != NULL) {

            delete  sample->minFrequency;
            sample->minFrequency=NULL;
        }
        if (sample->maxFrequency != NULL) {

            delete  sample->maxFrequency;
            sample->maxFrequency=NULL;
        }
        if (sample->switchInfo != NULL) {
            tms::PowerSwitchInfo_finalize_w_params(sample->switchInfo,deallocParams);

            delete  sample->switchInfo;
            sample->switchInfo=NULL;
        }
    }

    RTIBool PowerPortInfo_copy(
        PowerPortInfo* dst,
        const PowerPortInfo* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyLong (
                &dst->portNumber, 
                &src->portNumber)) { 
                return RTI_FALSE;
            }
            if (!tms::CircuitWiring_copy(
                &dst->wiring,
                (const tms::CircuitWiring*)&src->wiring)) {
                return RTI_FALSE;
            } 
            if (!tms::PowerPortDirectionality_copy(
                &dst->directionality,
                (const tms::PowerPortDirectionality*)&src->directionality)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyBoolean (
                &dst->hasSwitch, 
                &src->hasSwitch)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->hasExternalMeter, 
                &src->hasExternalMeter)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->hasInternalMeter, 
                &src->hasInternalMeter)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->hasSummaryMeasurementUpdate, 
                &src->hasSummaryMeasurementUpdate)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minAmperage, 
                &src->minAmperage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxAmperage, 
                &src->maxAmperage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->shortCircuitAmperage, 
                &src->shortCircuitAmperage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->minVoltage, 
                &src->minVoltage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxVoltage, 
                &src->maxVoltage)) { 
                return RTI_FALSE;
            }
            if (src->minFrequency!=NULL) {
                if (dst->minFrequency==NULL) {

                    dst->minFrequency = new (std::nothrow)   DDS_Float ();
                    if (dst->minFrequency==NULL) {
                        return RTI_FALSE;
                    }

                    if (!RTICdrType_initFloat(dst->minFrequency)) {
                        return RTI_FALSE;
                    }
                }
                if (!RTICdrType_copyFloat (
                    dst->minFrequency, 
                    src->minFrequency)) { 
                    return RTI_FALSE;
                }
            } else {
                if (dst->minFrequency != NULL) {
                    delete  dst->minFrequency;
                    dst->minFrequency=NULL;
                }
            }
            if (src->maxFrequency!=NULL) {
                if (dst->maxFrequency==NULL) {

                    dst->maxFrequency = new (std::nothrow)   DDS_Float ();
                    if (dst->maxFrequency==NULL) {
                        return RTI_FALSE;
                    }

                    if (!RTICdrType_initFloat(dst->maxFrequency)) {
                        return RTI_FALSE;
                    }
                }
                if (!RTICdrType_copyFloat (
                    dst->maxFrequency, 
                    src->maxFrequency)) { 
                    return RTI_FALSE;
                }
            } else {
                if (dst->maxFrequency != NULL) {
                    delete  dst->maxFrequency;
                    dst->maxFrequency=NULL;
                }
            }
            if (!tms::PowerConnectorInfo_copy(
                &dst->connectorInfo,
                (const tms::PowerConnectorInfo*)&src->connectorInfo)) {
                return RTI_FALSE;
            } 
            if (src->switchInfo!=NULL) {
                if (dst->switchInfo==NULL) {

                    dst->switchInfo = new (std::nothrow)   tms::PowerSwitchInfo ();
                    if (dst->switchInfo==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::PowerSwitchInfo_initialize_ex(
                        dst->switchInfo, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::PowerSwitchInfo_copy(
                    dst->switchInfo,
                    (const tms::PowerSwitchInfo*)src->switchInfo)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->switchInfo != NULL) {
                    tms::PowerSwitchInfo_finalize_w_params(dst->switchInfo, deallocParams);
                    delete  dst->switchInfo;
                    dst->switchInfo=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

