    RTIBool PowerSwitchStatus_copy(
        PowerSwitchStatus* dst,
        const PowerSwitchStatus* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::CircuitContinuity_copy(
                &dst->presentContinuity,
                (const tms::CircuitContinuity*)&src->presentContinuity)) {
                return RTI_FALSE;
            } 
            if (!tms::CircuitContinuity_copy(
                &dst->futureContinuity,
                (const tms::CircuitContinuity*)&src->futureContinuity)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyBoolean (
                &dst->requestLock, 
                &src->requestLock)) { 
                return RTI_FALSE;
            }
            if (!tms::PowerSwitchReason_copy(
                &dst->presentContinuityReason,
                (const tms::PowerSwitchReason*)&src->presentContinuityReason)) {
                return RTI_FALSE;
            } 
            if (src->presentContinuityActor!=NULL) {
                if (dst->presentContinuityActor==NULL) {
                    dst->presentContinuityActor= DDS_String_alloc (((tms::Identity_MAXLEN)));
                    ;
                    if (dst->presentContinuityActor == NULL) {
                        return RTI_FALSE;
                    }       
                }
                if (!RTICdrType_copyStringEx (
                    &dst->presentContinuityActor
                    ,
                    src->presentContinuityActor, 
                    ((tms::Identity_MAXLEN)) + 1,
                    RTI_FALSE)){
                    return RTI_FALSE;
                }
            } else {
                if (dst->presentContinuityActor != NULL) {
                    DDS_String_free(dst->presentContinuityActor);   
                    dst->presentContinuityActor = NULL;     
                }
            }
            if (!tms::PowerSwitchTransitionCode_copy(
                &dst->futureContinuityReason,
                (const tms::PowerSwitchTransitionCode*)&src->futureContinuityReason)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

