    RTIBool ParameterMetadata_copy(
        ParameterMetadata* dst,
        const ParameterMetadata* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->name
                ,
                src->name, 
                ((tms::String1_32_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyStringEx (
                &dst->units
                ,
                src->units, 
                ((tms::String16_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->nominalMinValue, 
                &src->nominalMinValue)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->nominalMaxValue, 
                &src->nominalMaxValue)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->hardMinValue, 
                &src->hardMinValue)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->hardMaxValue, 
                &src->hardMaxValue)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->resolution, 
                &src->resolution)) { 
                return RTI_FALSE;
            }
            if (!tms::EnumLabelSequence_copy(
                &dst->enumLabels,
                (const tms::EnumLabelSequence*)&src->enumLabels)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

