    RTIBool PowerPortStatus_copy(
        PowerPortStatus* dst,
        const PowerPortStatus* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyLong (
                &dst->portNumber, 
                &src->portNumber)) { 
                return RTI_FALSE;
            }
            if (!tms::CableSenseStatus_copy(
                &dst->cableStatus,
                (const tms::CableSenseStatus*)&src->cableStatus)) {
                return RTI_FALSE;
            } 
            if (src->cableId!=NULL) {
                if (dst->cableId==NULL) {
                    dst->cableId= DDS_String_alloc (((tms::Identity_MAXLEN)));
                    ;
                    if (dst->cableId == NULL) {
                        return RTI_FALSE;
                    }       
                }
                if (!RTICdrType_copyStringEx (
                    &dst->cableId
                    ,
                    src->cableId, 
                    ((tms::Identity_MAXLEN)) + 1,
                    RTI_FALSE)){
                    return RTI_FALSE;
                }
            } else {
                if (dst->cableId != NULL) {
                    DDS_String_free(dst->cableId);   
                    dst->cableId = NULL;     
                }
            }
            if (src->connection!=NULL) {
                if (dst->connection==NULL) {

                    dst->connection = new (std::nothrow)   tms::PowerPortId ();
                    if (dst->connection==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::PowerPortId_initialize_ex(
                        dst->connection, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::PowerPortId_copy(
                    dst->connection,
                    (const tms::PowerPortId*)src->connection)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->connection != NULL) {
                    tms::PowerPortId_finalize_w_params(dst->connection, deallocParams);
                    delete  dst->connection;
                    dst->connection=NULL;
                }
            }
            if (src->switchStatus!=NULL) {
                if (dst->switchStatus==NULL) {

                    dst->switchStatus = new (std::nothrow)   tms::PowerSwitchStatus ();
                    if (dst->switchStatus==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::PowerSwitchStatus_initialize_ex(
                        dst->switchStatus, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::PowerSwitchStatus_copy(
                    dst->switchStatus,
                    (const tms::PowerSwitchStatus*)src->switchStatus)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->switchStatus != NULL) {
                    tms::PowerSwitchStatus_finalize_w_params(dst->switchStatus, deallocParams);
                    delete  dst->switchStatus;
                    dst->switchStatus=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

