    RTIBool PowerConnectionId_copy(
        PowerConnectionId* dst,
        const PowerConnectionId* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::PowerPortId_copy(
                &dst->portA,
                (const tms::PowerPortId*)&src->portA)) {
                return RTI_FALSE;
            } 
            if (src->portB!=NULL) {
                if (dst->portB==NULL) {

                    dst->portB = new (std::nothrow)   tms::PowerPortId ();
                    if (dst->portB==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::PowerPortId_initialize_ex(
                        dst->portB, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::PowerPortId_copy(
                    dst->portB,
                    (const tms::PowerPortId*)src->portB)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->portB != NULL) {
                    tms::PowerPortId_finalize_w_params(dst->portB, deallocParams);
                    delete  dst->portB;
                    dst->portB=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

