    RTIBool ActiveDiagnosticState_copy(
        ActiveDiagnosticState* dst,
        const ActiveDiagnosticState* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::DiagnosticTroubleCodeSequence_copy(
                &dst->codes,
                (const tms::DiagnosticTroubleCodeSequence*)&src->codes)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyUnsignedLong (
                &dst->overflow, 
                &src->overflow)) { 
                return RTI_FALSE;
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

