    RTIBool AuthorizationToEnergizeReply_copy(
        AuthorizationToEnergizeReply* dst,
        const AuthorizationToEnergizeReply* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::GridRequest_copy(
                &dst->relatedRequestId,
                (const tms::GridRequest*)&src->relatedRequestId)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyUnsignedLongLong (
                &dst->relatedSequenceId, 
                &src->relatedSequenceId)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyStringEx (
                &dst->energizeRequestingDeviceId
                ,
                src->energizeRequestingDeviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyUnsignedLongLong (
                &dst->energizeSequenceId, 
                &src->energizeSequenceId)) { 
                return RTI_FALSE;
            }
            if (!tms::PowerPortNumberSequence_copy(
                &dst->powerPorts,
                (const tms::PowerPortNumberSequence*)&src->powerPorts)) {
                return RTI_FALSE;
            } 
            if (src->userId!=NULL) {
                if (dst->userId==NULL) {
                    dst->userId= DDS_String_alloc (((tms::Identity_MAXLEN)));
                    ;
                    if (dst->userId == NULL) {
                        return RTI_FALSE;
                    }       
                }
                if (!RTICdrType_copyStringEx (
                    &dst->userId
                    ,
                    src->userId, 
                    ((tms::Identity_MAXLEN)) + 1,
                    RTI_FALSE)){
                    return RTI_FALSE;
                }
            } else {
                if (dst->userId != NULL) {
                    DDS_String_free(dst->userId);   
                    dst->userId = NULL;     
                }
            }
            if (!RTICdrType_copyBoolean (
                &dst->accept, 
                &src->accept)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->deny, 
                &src->deny)) { 
                return RTI_FALSE;
            }
            if (!tms::ClockRealtime_copy(
                &dst->timeOfReview,
                (const tms::ClockRealtime*)&src->timeOfReview)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

