    void DeviceIcon_finalize_ex(
        DeviceIcon* sample,RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParams =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;

        if (sample==NULL) {
            return;
        } 

        deallocParams.delete_pointers = (DDS_Boolean)deletePointers;

        tms::DeviceIcon_finalize_w_params(
            sample,&deallocParams);
    }

    void DeviceIcon_finalize_w_params(
        DeviceIcon* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        if (sample->deviceId != NULL) {
            DDS_String_free(sample->deviceId);
            sample->deviceId=NULL;

        }
        if (sample->mimeType != NULL) {
            DDS_String_free(sample->mimeType);
            sample->mimeType=NULL;

        }
        tms::OctetSequence_finalize_w_params(&sample->data,deallocParams);

    }

    void DeviceIcon_finalize_optional_members(
        DeviceIcon* sample, RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParamsTmp =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
        struct DDS_TypeDeallocationParams_t * deallocParams =
        &deallocParamsTmp;

        if (sample==NULL) {
            return;
        } 
        if (deallocParams) {} /* To avoid warnings */

        deallocParamsTmp.delete_pointers = (DDS_Boolean)deletePointers;
        deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;

    }

    RTIBool DeviceIcon_copy(
        DeviceIcon* dst,
        const DeviceIcon* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyStringEx (
                &dst->mimeType
                ,
                src->mimeType, 
                ((tms::String32_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::OctetSequence_copy(
                &dst->data,
                (const tms::OctetSequence*)&src->data)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

