    RTIBool DeviceIntent_copy(
        DeviceIntent* dst,
        const DeviceIntent* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyBoolean (
                &dst->battleShort, 
                &src->battleShort)) { 
                return RTI_FALSE;
            }
            if (!tms::OperatorPriority_copy(
                &dst->priority,
                (const tms::OperatorPriority*)&src->priority)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

