    RTIBool ControlParameterState_copy(
        ControlParameterState* dst,
        const ControlParameterState* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::ConfigId_copy(
                &dst->config,
                (const tms::ConfigId*)&src->config)) {
                return RTI_FALSE;
            } 
            if (!tms::ParameterValueSequence_copy(
                &dst->parameters,
                (const tms::ParameterValueSequence*)&src->parameters)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

