    RTIBool GroundingCircuitRequest_copy(
        GroundingCircuitRequest* dst,
        const GroundingCircuitRequest* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::DeviceConfigRequest_copy(
                &dst->requestId,
                (const tms::DeviceConfigRequest*)&src->requestId)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyUnsignedLongLong (
                &dst->sequenceId, 
                &src->sequenceId)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyLong (
                &dst->groundNumber, 
                &src->groundNumber)) { 
                return RTI_FALSE;
            }
            if (!tms::DesiredCircuitContinuity_copy(
                &dst->control,
                (const tms::DesiredCircuitContinuity*)&src->control)) {
                return RTI_FALSE;
            } 
            if (!tms::DesiredCircuitContinuity_copy(
                &dst->pulse,
                (const tms::DesiredCircuitContinuity*)&src->pulse)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

