            if (!tms::MicrogridIntent_copy(
                &dst->microgrid,
                (const tms::MicrogridIntent*)&src->microgrid)) {
                return RTI_FALSE;
            } 
            if (!tms::DeviceIntentSequence_copy(
                &dst->devices,
                (const tms::DeviceIntentSequence*)&src->devices)) {
                return RTI_FALSE;
            } 
