    RTIBool PowerConnection_copy(
        PowerConnection* dst,
        const PowerConnection* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::PowerConnectionId_copy(
                &dst->connectionId,
                (const tms::PowerConnectionId*)&src->connectionId)) {
                return RTI_FALSE;
            } 
            if (!tms::PowerConnectionDetectionType_copy(
                &dst->detectionType,
                (const tms::PowerConnectionDetectionType*)&src->detectionType)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyStringEx (
                &dst->detectionSource
                ,
                src->detectionSource, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->detectionConfidence, 
                &src->detectionConfidence)) { 
                return RTI_FALSE;
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

