    RTIBool PowerSwitchRequest_initialize_w_params(
        PowerSwitchRequest *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        if (!tms::PowerPortConfigRequest_initialize_w_params(
            &sample->requestId,
            allocParams)) {
            return RTI_FALSE;
        }
        sample->sequenceId = 0ull;

        sample->continuity = tms::DCC_UNKNOWN;
        if (!allocParams->allocate_optional_members) {
            sample->switchConditions=NULL;
        } else {   
            if (allocParams->allocate_memory) {
                sample->switchConditions = new (std::nothrow)   tms::PowerSwitchCloseConditions ();
                if (sample->switchConditions==NULL) {
                    return RTI_FALSE;
                }
                if (!tms::PowerSwitchCloseConditions_initialize_w_params(
                    sample->switchConditions,
                    allocParams)) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->switchConditions!=NULL) {
                    if (!tms::PowerSwitchCloseConditions_initialize_w_params(
                        sample->switchConditions,
                        allocParams)) {
                        return RTI_FALSE;
                    }
                }   
            }
        }
        return RTI_TRUE;
    }
