    void PowerSwitchRequest_finalize_w_params(
        PowerSwitchRequest* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        tms::PowerPortConfigRequest_finalize_w_params(&sample->requestId,deallocParams);

        tms::DesiredCircuitContinuity_finalize_w_params(&sample->continuity,deallocParams);

        if (deallocParams->delete_optional_members) {
            if (sample->switchConditions != NULL) {
                tms::PowerSwitchCloseConditions_finalize_w_params(sample->switchConditions,deallocParams);

                delete  sample->switchConditions;
                sample->switchConditions=NULL;
            }
        }
    }

    void PowerSwitchRequest_finalize_optional_members(
        PowerSwitchRequest* sample, RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParamsTmp =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
        struct DDS_TypeDeallocationParams_t * deallocParams =
        &deallocParamsTmp;

        if (sample==NULL) {
            return;
        } 
        if (deallocParams) {} /* To avoid warnings */

        deallocParamsTmp.delete_pointers = (DDS_Boolean)deletePointers;
        deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;

        if (sample->switchConditions != NULL) {
            tms::PowerSwitchCloseConditions_finalize_w_params(sample->switchConditions,deallocParams);

            delete  sample->switchConditions;
            sample->switchConditions=NULL;
        }
    }

    RTIBool PowerSwitchRequest_copy(
        PowerSwitchRequest* dst,
        const PowerSwitchRequest* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::PowerPortConfigRequest_copy(
                &dst->requestId,
                (const tms::PowerPortConfigRequest*)&src->requestId)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyUnsignedLongLong (
                &dst->sequenceId, 
                &src->sequenceId)) { 
                return RTI_FALSE;
            }
            if (!tms::DesiredCircuitContinuity_copy(
                &dst->continuity,
                (const tms::DesiredCircuitContinuity*)&src->continuity)) {
                return RTI_FALSE;
            } 
            if (src->switchConditions!=NULL) {
                if (dst->switchConditions==NULL) {

                    dst->switchConditions = new (std::nothrow)   tms::PowerSwitchCloseConditions ();
                    if (dst->switchConditions==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::PowerSwitchCloseConditions_initialize_ex(
                        dst->switchConditions, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::PowerSwitchCloseConditions_copy(
                    dst->switchConditions,
                    (const tms::PowerSwitchCloseConditions*)src->switchConditions)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->switchConditions != NULL) {
                    tms::PowerSwitchCloseConditions_finalize_w_params(dst->switchConditions, deallocParams);
                    delete  dst->switchConditions;
                    dst->switchConditions=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

