    RTIBool ConversionInfo_initialize(
        ConversionInfo* sample)
    {
        return tms::ConversionInfo_initialize_ex(
            sample, 
            RTI_TRUE, 
            RTI_TRUE);
    }
    RTIBool ConversionInfo_initialize_w_params(
        ConversionInfo *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        if (!tms::ConversionFeatureSequence_initialize_w_params(
            &sample->features,
            allocParams)) {
            return RTI_FALSE;
        }
        if (!allocParams->allocate_optional_members) {
            sample->activeConversion=NULL;
        } else {   
            if (allocParams->allocate_memory) {
                sample->activeConversion = new (std::nothrow)   tms::ActiveConversionInfo ();
                if (sample->activeConversion==NULL) {
                    return RTI_FALSE;
                }
                if (!tms::ActiveConversionInfo_initialize_w_params(
                    sample->activeConversion,
                    allocParams)) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->activeConversion!=NULL) {
                    if (!tms::ActiveConversionInfo_initialize_w_params(
                        sample->activeConversion,
                        allocParams)) {
                        return RTI_FALSE;
                    }
                }   
            }
        }
        if (!allocParams->allocate_optional_members) {
            sample->passiveConversion=NULL;
        } else {   
            if (allocParams->allocate_memory) {
                sample->passiveConversion = new (std::nothrow)   tms::PassiveConversionInfo ();
                if (sample->passiveConversion==NULL) {
                    return RTI_FALSE;
                }
                if (!tms::PassiveConversionInfo_initialize_w_params(
                    sample->passiveConversion,
                    allocParams)) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->passiveConversion!=NULL) {
                    if (!tms::PassiveConversionInfo_initialize_w_params(
                        sample->passiveConversion,
                        allocParams)) {
                        return RTI_FALSE;
                    }
                }   
            }
        }
        return RTI_TRUE;
    }
    RTIBool ConversionInfo_initialize_ex(
        ConversionInfo *sample,
        RTIBool allocatePointers, 
        RTIBool allocateMemory)
    {

        struct DDS_TypeAllocationParams_t allocParams =
        DDS_TYPE_ALLOCATION_PARAMS_DEFAULT;

        allocParams.allocate_pointers =  (DDS_Boolean)allocatePointers;
        allocParams.allocate_memory = (DDS_Boolean)allocateMemory;

        return tms::ConversionInfo_initialize_w_params(
            sample,
            &allocParams);
    }

    RTIBool ConversionInfo_finalize_w_return(
        ConversionInfo* sample)
    {
        tms::ConversionInfo_finalize_ex(sample, RTI_TRUE);

        return RTI_TRUE;
    }

    void ConversionInfo_finalize(
        ConversionInfo* sample)
    {

        tms::ConversionInfo_finalize_ex(sample,RTI_TRUE);
    }

    void ConversionInfo_finalize_ex(
        ConversionInfo* sample,RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParams =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;

        if (sample==NULL) {
            return;
        } 

        deallocParams.delete_pointers = (DDS_Boolean)deletePointers;

        tms::ConversionInfo_finalize_w_params(
            sample,&deallocParams);
    }

    void ConversionInfo_finalize_w_params(
        ConversionInfo* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        tms::ConversionFeatureSequence_finalize_w_params(&sample->features,deallocParams);

        if (deallocParams->delete_optional_members) {
            if (sample->activeConversion != NULL) {
                tms::ActiveConversionInfo_finalize_w_params(sample->activeConversion,deallocParams);

                delete  sample->activeConversion;
                sample->activeConversion=NULL;
            }
        }
        if (deallocParams->delete_optional_members) {
            if (sample->passiveConversion != NULL) {
                tms::PassiveConversionInfo_finalize_w_params(sample->passiveConversion,deallocParams);

                delete  sample->passiveConversion;
                sample->passiveConversion=NULL;
            }
        }
    }

    void ConversionInfo_finalize_optional_members(
        ConversionInfo* sample, RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParamsTmp =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
        struct DDS_TypeDeallocationParams_t * deallocParams =
        &deallocParamsTmp;

        if (sample==NULL) {
            return;
        } 
        if (deallocParams) {} /* To avoid warnings */

        deallocParamsTmp.delete_pointers = (DDS_Boolean)deletePointers;
        deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;

        if (sample->activeConversion != NULL) {
            tms::ActiveConversionInfo_finalize_w_params(sample->activeConversion,deallocParams);

            delete  sample->activeConversion;
            sample->activeConversion=NULL;
        }
        if (sample->passiveConversion != NULL) {
            tms::PassiveConversionInfo_finalize_w_params(sample->passiveConversion,deallocParams);

            delete  sample->passiveConversion;
            sample->passiveConversion=NULL;
        }
    }

    RTIBool ConversionInfo_copy(
        ConversionInfo* dst,
        const ConversionInfo* src)
    {
        try {

            struct DDS_TypeDeallocationParams_t deallocParamsTmp =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            struct DDS_TypeDeallocationParams_t * deallocParams =
            &deallocParamsTmp;

            if (deallocParams) {} /* To avoid warnings */

            deallocParamsTmp.delete_pointers = DDS_BOOLEAN_TRUE;
            deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;    

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!tms::ConversionFeatureSequence_copy(
                &dst->features,
                (const tms::ConversionFeatureSequence*)&src->features)) {
                return RTI_FALSE;
            } 
            if (src->activeConversion!=NULL) {
                if (dst->activeConversion==NULL) {

                    dst->activeConversion = new (std::nothrow)   tms::ActiveConversionInfo ();
                    if (dst->activeConversion==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::ActiveConversionInfo_initialize_ex(
                        dst->activeConversion, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::ActiveConversionInfo_copy(
                    dst->activeConversion,
                    (const tms::ActiveConversionInfo*)src->activeConversion)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->activeConversion != NULL) {
                    tms::ActiveConversionInfo_finalize_w_params(dst->activeConversion, deallocParams);
                    delete  dst->activeConversion;
                    dst->activeConversion=NULL;
                }
            }
            if (src->passiveConversion!=NULL) {
                if (dst->passiveConversion==NULL) {

                    dst->passiveConversion = new (std::nothrow)   tms::PassiveConversionInfo ();
                    if (dst->passiveConversion==NULL) {
                        return RTI_FALSE;
                    }

                    if (!tms::PassiveConversionInfo_initialize_ex(
                        dst->passiveConversion, 
                        RTI_TRUE, 
                        RTI_TRUE)) {
                        return RTI_FALSE;
                    }
                }
                if (!tms::PassiveConversionInfo_copy(
                    dst->passiveConversion,
                    (const tms::PassiveConversionInfo*)src->passiveConversion)) {
                    return RTI_FALSE;
                } 
            } else {
                if (dst->passiveConversion != NULL) {
                    tms::PassiveConversionInfo_finalize_w_params(dst->passiveConversion, deallocParams);
                    delete  dst->passiveConversion;
                    dst->passiveConversion=NULL;
                }
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

