    RTIBool Reply_initialize_w_params(
        Reply *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        if (allocParams->allocate_memory) {
            sample->requestingDeviceId = DDS_String_alloc(((tms::Identity_MAXLEN)));
            if (sample->requestingDeviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->requestingDeviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
            }
            if (sample->requestingDeviceId == NULL) {
                return RTI_FALSE;
            }
        } else {
            if (sample->requestingDeviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->requestingDeviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
                if (sample->requestingDeviceId == NULL) {
                    return RTI_FALSE;
                }
            }
        }

        if (allocParams->allocate_memory) {
            sample->targetDeviceId = DDS_String_alloc(((tms::Identity_MAXLEN)));
            if (sample->targetDeviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->targetDeviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
            }
            if (sample->targetDeviceId == NULL) {
                return RTI_FALSE;
            }
        } else {
            if (sample->targetDeviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->targetDeviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
                if (sample->targetDeviceId == NULL) {
                    return RTI_FALSE;
                }
            }
        }

        sample->config = tms::CONFIG_UNKNOWN;
        sample->portNumber = 0;

        sample->requestSequenceId = 0ull;

        if (!tms::ReplyStatus_initialize_w_params(
            &sample->status,
            allocParams)) {
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }
