    void Reply_finalize_ex(
        Reply* sample,RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParams =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;

        if (sample==NULL) {
            return;
        } 

        deallocParams.delete_pointers = (DDS_Boolean)deletePointers;

        tms::Reply_finalize_w_params(
            sample,&deallocParams);
    }

    void Reply_finalize_w_params(
        Reply* sample,const struct DDS_TypeDeallocationParams_t * deallocParams)
    {

        if (sample==NULL) {
            return;
        }

        if (deallocParams == NULL) {
            return;
        }

        if (sample->requestingDeviceId != NULL) {
            DDS_String_free(sample->requestingDeviceId);
            sample->requestingDeviceId=NULL;

        }
        if (sample->targetDeviceId != NULL) {
            DDS_String_free(sample->targetDeviceId);
            sample->targetDeviceId=NULL;

        }
        tms::ConfigId_finalize_w_params(&sample->config,deallocParams);

        tms::ReplyStatus_finalize_w_params(&sample->status,deallocParams);

    }

    void Reply_finalize_optional_members(
        Reply* sample, RTIBool deletePointers)
    {
        struct DDS_TypeDeallocationParams_t deallocParamsTmp =
        DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
        struct DDS_TypeDeallocationParams_t * deallocParams =
        &deallocParamsTmp;

        if (sample==NULL) {
            return;
        } 
        if (deallocParams) {} /* To avoid warnings */

        deallocParamsTmp.delete_pointers = (DDS_Boolean)deletePointers;
        deallocParamsTmp.delete_optional_members = DDS_BOOLEAN_TRUE;

    }

    RTIBool Reply_copy(
        Reply* dst,
        const Reply* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->requestingDeviceId
                ,
                src->requestingDeviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyStringEx (
                &dst->targetDeviceId
                ,
                src->targetDeviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!tms::ConfigId_copy(
                &dst->config,
                (const tms::ConfigId*)&src->config)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyLong (
                &dst->portNumber, 
                &src->portNumber)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyUnsignedLongLong (
                &dst->requestSequenceId, 
                &src->requestSequenceId)) { 
                return RTI_FALSE;
            }
            if (!tms::ReplyStatus_copy(
                &dst->status,
                (const tms::ReplyStatus*)&src->status)) {
                return RTI_FALSE;
            } 

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

