        RTIBool LoadSharingParameters_initialize_w_params(
            LoadSharingParameters *sample,
            const struct DDS_TypeAllocationParams_t *allocParams)
        {

            if (sample == NULL) {
                return RTI_FALSE;
            }
            if (allocParams == NULL) {
                return RTI_FALSE;
            }

            sample->portNumber = 0;

            if (!tms::ControlCurve_initialize_w_params(
                &sample->referenceFrequency,
                allocParams)) {
                return RTI_FALSE;
            }
            if (!tms::ControlCurve_initialize_w_params(
                &sample->referenceVoltage,
                allocParams)) {
                return RTI_FALSE;
            }
            sample->minRealPower = 0.0f;

            sample->maxRealPower = 0.0f;

            sample->minFrequency = 0.0f;

            sample->maxFrequency = 0.0f;

            sample->minReactivePower = 0.0f;

            sample->maxReactivePower = 0.0f;

            sample->minVoltage = 0.0f;

            sample->maxVoltage = 0.0f;

            return RTI_TRUE;
        }
