        RTIBool LoadSharingState_initialize_w_params(
            LoadSharingState *sample,
            const struct DDS_TypeAllocationParams_t *allocParams)
        {

            if (sample == NULL) {
                return RTI_FALSE;
            }
            if (allocParams == NULL) {
                return RTI_FALSE;
            }

            if (allocParams->allocate_memory) {
                sample->deviceId = DDS_String_alloc(((tms::Identity_MAXLEN)));
                if (sample->deviceId != NULL) {
                    RTIOsapiUtility_unusedReturnValue(
                        RTICdrType_copyStringEx(
                            &sample->deviceId,
                            "",
                            ((tms::Identity_MAXLEN)),
                            RTI_FALSE),
                            RTIBool);
                }
                if (sample->deviceId == NULL) {
                    return RTI_FALSE;
                }
            } else {
                if (sample->deviceId != NULL) {
                    RTIOsapiUtility_unusedReturnValue(
                        RTICdrType_copyStringEx(
                            &sample->deviceId,
                            "",
                            ((tms::Identity_MAXLEN)),
                            RTI_FALSE),
                            RTIBool);
                    if (sample->deviceId == NULL) {
                        return RTI_FALSE;
                    }
                }
            }

            sample->config = tms::CONFIG_UNKNOWN;
            if (!tms::dc::LoadSharingParameterSequence_initialize_w_params(
                &sample->parameters,
                allocParams)) {
                return RTI_FALSE;
            }
            return RTI_TRUE;
        }
        RTIBool LoadSharingState_initialize_ex(
            LoadSharingState *sample,
            RTIBool allocatePointers, 
            RTIBool allocateMemory)
        {

            struct DDS_TypeAllocationParams_t allocParams =
            DDS_TYPE_ALLOCATION_PARAMS_DEFAULT;

            allocParams.allocate_pointers =  (DDS_Boolean)allocatePointers;
            allocParams.allocate_memory = (DDS_Boolean)allocateMemory;

            return tms::dc::LoadSharingState_initialize_w_params(
                sample,
                &allocParams);
        }

