    RTIBool StorageUpdate_initialize_w_params(
        StorageUpdate *sample,
        const struct DDS_TypeAllocationParams_t *allocParams)
    {

        if (sample == NULL) {
            return RTI_FALSE;
        }
        if (allocParams == NULL) {
            return RTI_FALSE;
        }

        if (allocParams->allocate_memory) {
            sample->deviceId = DDS_String_alloc(((tms::Identity_MAXLEN)));
            if (sample->deviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->deviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
            }
            if (sample->deviceId == NULL) {
                return RTI_FALSE;
            }
        } else {
            if (sample->deviceId != NULL) {
                RTIOsapiUtility_unusedReturnValue(
                    RTICdrType_copyStringEx(
                        &sample->deviceId,
                        "",
                        ((tms::Identity_MAXLEN)),
                        RTI_FALSE),
                        RTIBool);
                if (sample->deviceId == NULL) {
                    return RTI_FALSE;
                }
            }
        }

        sample->internalVoltage = 0.0f;

        sample->stateOfCharge = 0.0f;

        sample->availableEnergy = 0.0f;

        sample->holdTime = 0.0f;

        if (!tms::Curve2D_initialize_w_params(
            &sample->chargeTime,
            allocParams)) {
            return RTI_FALSE;
        }
        if (!tms::Curve2D_initialize_w_params(
            &sample->dischargeTime,
            allocParams)) {
            return RTI_FALSE;
        }
        if (!tms::Curve2D_initialize_w_params(
            &sample->maxChargeTime,
            allocParams)) {
            return RTI_FALSE;
        }
        if (!tms::Curve2D_initialize_w_params(
            &sample->maxDischargeTime,
            allocParams)) {
            return RTI_FALSE;
        }
        sample->maxChargeRate = 0.0f;

        sample->maxDischargeRate = 0.0f;

        return RTI_TRUE;
    }
