    RTIBool StorageUpdate_copy(
        StorageUpdate* dst,
        const StorageUpdate* src)
    {
        try {

            if (dst == NULL || src == NULL) {
                return RTI_FALSE;
            }

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->internalVoltage, 
                &src->internalVoltage)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->stateOfCharge, 
                &src->stateOfCharge)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->availableEnergy, 
                &src->availableEnergy)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->holdTime, 
                &src->holdTime)) { 
                return RTI_FALSE;
            }
            if (!tms::Curve2D_copy(
                &dst->chargeTime,
                (const tms::Curve2D*)&src->chargeTime)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->dischargeTime,
                (const tms::Curve2D*)&src->dischargeTime)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->maxChargeTime,
                (const tms::Curve2D*)&src->maxChargeTime)) {
                return RTI_FALSE;
            } 
            if (!tms::Curve2D_copy(
                &dst->maxDischargeTime,
                (const tms::Curve2D*)&src->maxDischargeTime)) {
                return RTI_FALSE;
            } 
            if (!RTICdrType_copyFloat (
                &dst->maxChargeRate, 
                &src->maxChargeRate)) { 
                return RTI_FALSE;
            }
            if (!RTICdrType_copyFloat (
                &dst->maxDischargeRate, 
                &src->maxDischargeRate)) { 
                return RTI_FALSE;
            }

            return RTI_TRUE;
        } catch (const std::bad_alloc&) {
            return RTI_FALSE;
        }
    }

